"""Current typed queries drive subtype, numeric, snow and threshold states."""
import json,unittest
import state_trigger_fixture as fixtures

class StateTriggerPredicateTests(fixtures.StateTriggerFixture,unittest.TestCase):
    def test_actual_endrek_counts_all_thrulls_and_triggers_above_seven(self):
        session=self.session(611651080);source=self.add(session.engine,'Endrek Sahr, Master Breeder',zone='hand');first=self.add(session.engine,'Grizzly Bears',zone='hand');second=self.add(session.engine,'Shivan Dragon',zone='hand');self.assert_closed(session,source)
        self.prepare(session,mana={'C':9,'B':1,'G':1,'R':2});self.checkpoint(session);self.cast_for(session,'A',source,reserve={'C':5,'G':1,'R':2});self.settle(session);self.cast_for(session,'A',first,reserve={'C':4,'R':2});self.settle(session);tokens=[c for c in session.state.cards.values() if c.zone=='battlefield' and c.is_token];self.assertEqual(2,len(tokens));self.assertEqual(0,self.trigger_count(session,source))
        self.cast(session,'A',second);self.resolve_top(session);self.assertEqual(1,self.trigger_count(session,source));tokens=[c for c in session.state.cards.values() if c.zone=='battlefield' and c.is_token];self.assertEqual(8,len(tokens));session=self.replay(session,load=True);self.settle(session);self.assertEqual('graveyard',session.state.cards[source.object_id].zone);self.assertEqual('battlefield',session.state.cards[second.object_id].zone);self.assertEqual(8,len([c for c in session.state.cards.values() if c.zone=='battlefield' and c.is_token]));self.replay(session,load=True)

    def test_actual_dwarf_presence_is_controller_relative(self):
        session=self.session(611651090);source=self.add(session.engine,'Goblins of the Flarg',zone='hand');foreign=self.add(session.engine,'Dwarven Trader',seat='B',ref='foreign-dwarf');own=self.add(session.engine,'Dwarven Trader',zone='hand',ref='own-dwarf');self.assert_closed(session,source)
        self.prepare(session,mana={'R':2});self.checkpoint(session);self.cast_for(session,'A',source,reserve={'R':1});self.settle(session);self.assertEqual(0,self.trigger_count(session,source));self.cast(session,'A',own);self.resolve_top(session);self.assertEqual(1,self.trigger_count(session,source));self.settle(session);self.assertEqual('graveyard',session.state.cards[source.object_id].zone);self.assertEqual('battlefield',session.state.cards[foreign.object_id].zone);self.replay(session,load=True)

    def test_actual_armodon_reads_layered_toughness_and_keeps_trigger_after_growth_response(self):
        session=self.session(611651100);source=self.add(session.engine,'Endangered Armodon',zone='hand');body=self.add(session.engine,'Shivan Dragon');shrink=self.add(session.engine,'Last Gasp',zone='hand');grow=self.add(session.engine,'Giant Growth',zone='hand');self.add(session.engine,'Swamp');self.add(session.engine,'Wastes');self.add(session.engine,'Forest');self.assert_closed(session,source)
        self.prepare(session,mana={'C':2,'G':2});self.checkpoint(session);self.cast(session,'A',source);self.settle(session);self.assertEqual(0,self.trigger_count(session,source));self.cast_for(session,'A',shrink,[body.ref],reserve={'G':1});self.resolve_top(session);self.assertEqual(2,session.engine._numeric_stat(body.object_id,'toughness'));self.assertEqual(1,self.trigger_count(session,source));self.cast(session,'A',grow,[body.ref]);self.resolve_top(session);self.assertEqual(5,session.engine._numeric_stat(body.object_id,'toughness'));self.settle(session);self.assertEqual('graveyard',session.state.cards[source.object_id].zone);self.replay(session,load=True)

    def test_actual_ronom_requires_a_snow_land_and_ordinary_islands_do_not_satisfy_it(self):
        session=self.session(611651110);source=self.add(session.engine,'Ronom Serpent',zone='hand');land=self.add(session.engine,'Snow-Covered Island');self.add(session.engine,'Island',ref='ordinary-island-1');self.add(session.engine,'Island',ref='ordinary-island-2');bounce=self.add(session.engine,'Boomerang',zone='hand');self.assert_closed(session,source)
        self.prepare(session,mana={'C':5,'U':1});self.checkpoint(session);self.cast(session,'A',source);self.settle(session);self.assertEqual(0,self.trigger_count(session,source));self.cast(session,'A',bounce,[land.ref]);self.resolve_top(session);self.assertEqual(1,self.trigger_count(session,source));self.settle(session);self.assertEqual('graveyard',session.state.cards[source.object_id].zone);self.replay(session,load=True)

    def test_actual_face_down_serpent_does_not_trigger_until_turned_face_up(self):
        session=self.session(611651120);source=self.add(session.engine,'Slipstream Serpent',zone='hand');self.assert_closed(session,source);self.prepare(session,mana={'C':8,'U':1});self.checkpoint(session);action=next(a for a in session.packet('pilot:A',full=True)['decision']['ctx']['legal']['actions'] if a['id']=='cast-morph:'+source.ref);result=session.act('pilot:A',{'action_id':action['id'],'pay':'auto'});self.assertTrue(result.ok,result.summary);self.settle(session);self.assertEqual(0,self.trigger_count(session,source))
        for seat in 'BCD':self.assertNotIn('Slipstream Serpent',json.dumps(session.packet('pilot:'+seat,full=True)))
        self.priority(session,'A');action=next(a for a in session.packet('pilot:A',full=True)['decision']['ctx']['legal']['actions'] if a['id'].startswith('turn-face-up:'+source.ref));result=session.act('pilot:A',{'action_id':action['id'],'pay':'auto'});self.assertTrue(result.ok,result.summary);self.assertEqual(1,self.trigger_count(session,source));self.settle(session);self.assertEqual('graveyard',session.state.cards[source.object_id].zone);self.replay(session,load=True)

    def test_actual_free_cast_hand_change_is_observed_before_later_maro_sacrifice_cost(self):
        session=self.session(611651130)
        for oid in tuple(session.state.players['A'].zones['hand']):session.engine.move_card(oid,'library',reason='Prepared exact hand size before state sources exist',semantic_events=False)
        spell=self.add(session.engine,"Altar's Reap",zone='hand');self.add(session.engine,'Shock',zone='hand',ref='retained-hand-1');self.add(session.engine,'Shock',zone='hand',ref='retained-hand-2');maro=self.add(session.engine,'Maro');source=self.add(session.engine,'Endangered Armodon');self.add(session.engine,'Omniscience');self.assert_closed(session,source);self.assert_closed(session,maro);self.assert_closed(session,spell);self.prepare(session);self.checkpoint(session);self.assertEqual(3,session.engine._numeric_stat(maro.object_id,'toughness'))
        action=self.action(session,'A',spell);option=next(o for o in action['cost_options'] if o['id'].startswith('battlefield-alternative:'));result=session.act('pilot:A',{'action_id':action['id'],'cost_option':option['id'],'pay':'auto','sacrifice_cards':[maro.ref]});self.assertTrue(result.ok,result.summary);self.assertEqual('graveyard',session.state.cards[maro.object_id].zone);self.assertEqual(1,self.trigger_count(session,source));session=self.replay(session,load=True);self.settle(session);self.assertEqual('graveyard',session.state.cards[source.object_id].zone);self.replay(session,load=True)
